const express = require('express');
const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

const cors = require('cors');
app.use(cors());

mongoose.connect('mongodb://localhost:27017/exam_center', {
    useNewUrlParser: true,
    useUnifiedTopology: true,
});

const db = mongoose.connection;
db.on('error', console.error.bind(console, 'connection error:'));
db.once('open', () => {
    console.log('Database connected');
});

const examDataSchema = new mongoose.Schema({
    examName: { type: String, required: true },
    date: { type: Date, required: true },
    studentsAttended: { type: Number, required: true },
});

const franchiseSchema = new mongoose.Schema({
    name: { type: String, required: true },
    location: { type: String, required: true },
    status: { type: String, enum: ['active', 'inactive'], default: 'active' },
    contactNumber: { type: String, required: true },
    examData: [examDataSchema],
    admin: { type: mongoose.Schema.Types.ObjectId, ref: 'User' }, // Added admin reference
});

const Franchise = mongoose.model('Franchise', franchiseSchema);

const userSchema = new mongoose.Schema({
    username: { type: String, required: true, unique: true },
    password: { type: String, required: true },
    name: { type: String, required: true },
    role: { type: String, enum: ['superadmin', 'admin', 'user'], required: true },
    franchise: { type: mongoose.Schema.Types.ObjectId, ref: 'Franchise' },
});

const User = mongoose.model('User', userSchema);

const authenticate = (roles) => async (req, res, next) => {
    try {
        const token = req.headers.authorization.split(' ')[1];
        const decoded = jwt.verify(token, 'secret_key');
        req.user = decoded;

        if (!roles.includes(decoded.role)) {
            return res.status(403).json({ message: 'Access denied' });
        }

        next();
    } catch (error) {
        return res.status(401).json({ message: 'Unauthorized' });
    }
};

// Routes

// Login API
app.post('/api/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const user = await User.findOne({ username });
        if (!user) {
            return res.status(404).json({ message: 'User not found' });
        }

        if (password !== user.password) {
            return res.status(401).json({ message: 'Invalid credentials' });
        }

        const token = jwt.sign({ id: user._id, role: user.role }, 'secret_key', { expiresIn: '1h' });
        res.status(200).json({
            message: 'Login successful',
            user: {
                id: user._id,
                username: user.username,
                name: user.name,
                role: user.role,
            },
            token,
        });
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

// Admin Creation API (Only one admin for all franchises)
app.post('/admins', authenticate(['superadmin']), async (req, res) => {
    const { username, password, name } = req.body;
    try {
        // Check if an admin already exists
        const existingAdmin = await User.findOne({ role: 'admin' });
        if (existingAdmin) {
            return res.status(400).json({ message: 'There can only be one admin for all franchises.' });
        }

        // Create the new admin
        const admin = new User({
            username,
            password,
            name,
            role: 'admin',
        });

        await admin.save();

        // Set this admin for all existing franchises
        const franchises = await Franchise.find();
        for (let franchise of franchises) {
            franchise.admin = admin._id; // Assign this admin to the franchise
            await franchise.save();
        }

        res.status(201).json(admin);
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

// Franchise Creation API
app.post('/franchises', authenticate(['superadmin']), async (req, res) => {
    const { name, location, status, contactNumber } = req.body;
    try {
        const franchise = new Franchise({ name, location, status, contactNumber });
        await franchise.save();
        res.status(201).json(franchise);
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

// User Creation API
app.post('/users', authenticate(['admin', 'superadmin']), async (req, res) => {
    const { username, password, name, role, franchiseId } = req.body;

    try {
        // If the user is creating another admin, ensure only one admin exists
        if (role === 'admin') {
            const existingAdmin = await User.findOne({ role: 'admin' });
            if (existingAdmin) {
                return res.status(400).json({ message: 'There can only be one admin for all franchises.' });
            }
        }

        const franchise = await Franchise.findById(franchiseId);
        if (!franchise) {
            return res.status(404).json({ message: 'Franchise not found' });
        }

        const user = new User({
            username,
            password,
            name,
            role,
            franchise: franchiseId,
        });

        await user.save();
        res.status(201).json(user);
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

// Admin and Franchise Update API
app.put('/users/:id', authenticate(['admin', 'superadmin']), async (req, res) => {
    const { id } = req.params;
    const { username, password, name, role, franchiseId } = req.body;

    try {
        const user = await User.findById(id);

        if (!user) {
            return res.status(404).json({ message: 'User not found' });
        }

        if (req.user.role === 'admin' && req.user._id !== id) {
            return res.status(403).json({ message: 'Admins can only update their own account' });
        }

        if (role === 'admin' && req.user.role === 'superadmin') {
            const existingAdmin = await User.findOne({ role: 'admin' });
            if (existingAdmin) {
                return res.status(400).json({ message: 'There can only be one admin for all franchises.' });
            }
        }

        if (req.user.role === 'superadmin') {
            if (username) user.username = username;
            if (password) user.password = password;
            if (name) user.name = name;
            if (role) user.role = role;
            if (franchiseId) {
                const franchise = await Franchise.findById(franchiseId);
                if (!franchise) {
                    return res.status(404).json({ message: 'Franchise not found' });
                }
                user.franchise = franchiseId;
            }

            await user.save();
            return res.status(200).json(user);
        }

        if (req.user._id === id) {
            if (username) user.username = username;
            if (password) user.password = password;
            if (name) user.name = name;
            if (role) user.role = role;
            if (franchiseId) {
                const franchise = await Franchise.findById(franchiseId);
                if (!franchise) {
                    return res.status(404).json({ message: 'Franchise not found' });
                }
                user.franchise = franchiseId;
            }
            await user.save();
            return res.status(200).json(user);
        }

        return res.status(403).json({ message: 'You are not authorized to update this user.' });
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

// Route to get franchises associated with the user (only for authenticated users)
app.get('/franchises/associated', authenticate(['user', 'admin', 'superadmin']), async (req, res) => {
    try {
        if (req.user.role === 'user') {
            // If the user is a regular user, return only the franchise associated with them
            const user = await User.findById(req.user.id).populate('franchise');
            if (!user) {
                return res.status(404).json({ message: 'User not found' });
            }
            if (!user.franchise) {
                return res.status(404).json({ message: 'No franchise associated with this user' });
            }
            return res.status(200).json([user.franchise]); // Return the associated franchise as an array
        } else {
            // If the user is an admin or superadmin, return all franchises
            const franchises = await Franchise.find();
            res.status(200).json(franchises);
        }
    } catch (error) {
        res.status(500).json({ message: error.message });
    }
});

// Logout API
app.post('/api/logout', (req, res) => {
    console.log('Logout route triggered');
    res.status(200).json({ message: 'Logout successful' });
});

const PORT = 3001;
app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
